<?php
namespace Ishep\Http\Controllers;use Ishep\Bootstrap\Application as App;use Ishep\Http\Response;final class DashboardController{public function show(string $view,string $title):Response{$app=App::instance();$id=(int)($app->auth()->user()['id']??0);$canReview=$app->authorization()->hasRole($id,'administrator')||$app->authorization()->hasRole($id,'super_user');$permissions=$app->roles()->permissions($id);$canPortals=(bool)array_intersect($permissions,['jobs.post','jobs.moderate','bursaries.post','bursaries.moderate']);$canReports=in_array('reports.view',$permissions,true);return$app->render('dashboards/'.$view,['title'=>$title,'canReviewApplications'=>$canReview,'applicationCounts'=>$canReview?$app->applications()->counts():[],'documentCounts'=>$canReview?$app->documents()->counts():[],'canManagePortals'=>$canPortals,'portalCounts'=>$canPortals?$app->portals()->counts():[],'canReports'=>$canReports]);}}
